Import ListNotations.
Open Scope Z_scope.

Notation UNREG_W :=
  [(XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI); (0x7771a0%Z, 0x7771a3%Z); (0x777140%Z, 0x777142%Z)] (only parsing).

Definition unreg_loop_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' s0' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) (o1' o2' o3' o4' o5' : byte),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0' (Z_to_bv 64 0x2d65e8) a0' a1' a2' a3' a4' a5' a6' a7'
                  (Z_to_bv 64 2) (Z_to_bv 64 0x2556f) (Z_to_bv 64 0x2413d0) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x242330)
                  (Z_to_bv 64 0x227e98) (Z_to_bv 64 0x242370) (Z_to_bv 64 0x2422b8) (Z_to_bv 64 0x244ab8) (Z_to_bv 64 0)
                  t3' t4' t5' t6')
             F (Z_to_bv 64 0xafeec) fc None m' (seg_rom asegs)
    /\ munch UNREG_W m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' XS1_LO XS1_HI /\ stk asegs m' XS2_LO XS2_HI /\ stk asegs m' XS3_LO XS3_HI
    /\ rw_cells asegs m' 0x7771a0 [C1 o1'] /\ rw_cells asegs m' 0x777140 [C1 o2'] /\ rw_cells asegs m' 0x777141 [C1 o3'] /\ rw_cells asegs m' 0x7771a1 [C1 o4'] /\ rw_cells asegs m' 0x7771a2 [C1 o5'].

Lemma unreg_loop : forall (gs : list gdesc) (K : Z)
    (ra gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (sp : word) F fc (m : mem) (o1 o2 o3 o4 o5 : byte),
  Forall (fun g => gd_okb g = true) gs -> Z.of_nat (length gs) = K -> 1 <= K <= 1445 ->
  gds_at m (0x2413d0 - 64 * K) gs ->
  rw_cells asegs m 0x245798 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x24431c [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x2422d0 [C4 (Z_to_bv 64 1)] ->
  ro_cells asegs m 0x244ab8 [C8 (Z_to_bv 64 0x7fff8000)] ->
  ro_cells asegs m 0x2d6660 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0x227e98 [C8 (Z_to_bv 64 0x218338)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  rw_cells asegs m 0x7771a0 [C1 o1] -> rw_cells asegs m 0x777140 [C1 o2] -> rw_cells asegs m 0x777141 [C1 o3] -> rw_cells asegs m 0x7771a1 [C1 o4] -> rw_cells asegs m 0x7771a2 [C1 o5] ->
  mem_inv asegs m ->
  evt asegs (unreg_loop_post sp gp tp F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 0x2d65e8) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x2556f) (Z_to_bv 64 (0x2413d0 - 64 * K)) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x242330)
             (Z_to_bv 64 0x227e98) (Z_to_bv 64 0x242370) (Z_to_bv 64 0x2422b8) (Z_to_bv 64 0x244ab8) (Z_to_bv 64 K)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0xafce8) fc None m (seg_rom asegs)).
Proof.
